    if (!this._requirePermission(this.can_update(), i18n("SIGNAGE_MANAGER.SVC_NO_UPDATE_PLAYLISTS")))
      return;
    await Mh(playlist_id, items);
    this._setPlaylistMediaState(playlist_id, items, false);
    this._playlist_change.set(Date.now());
